import math
import numpy as np

def _paths(S0, r, sigma, T, z):
    return S0 * np.exp((r - sigma ** 2 / 2) * T + sigma * math.sqrt(T) * z)

def mc_control(S0, K, r, sigma, T, n, seed):
    """Call price with the discounted share as control: (price, SE, b)."""
    if n < 2:
        raise ValueError("a standard error needs at least two paths")
    z = np.random.default_rng(seed).standard_normal(n)
    ST = _paths(S0, r, sigma, T, z)
    y = math.exp(-r * T) * np.maximum(ST - K, 0.0)
    x = math.exp(-r * T) * ST                       # E[x] = S0 exactly
    b = np.cov(y, x)[0, 1] / np.var(x, ddof=1)      # b* from the paths
    a = y - b * (x - S0)
    return float(a.mean()), float(a.std(ddof=1) / math.sqrt(n)), float(b)

def vrf(rho):
    """Variance-reduction factor of a control with correlation rho."""
    return 1 / (1 - rho ** 2)

def mc_antithetic(S0, K, r, sigma, T, n, seed):
    """Call price from n payoffs in n // 2 antithetic pairs: (price, SE)."""
    m = n // 2
    if m < 2:
        raise ValueError("a standard error needs at least two pairs")
    z = np.random.default_rng(seed).standard_normal(m)
    f = lambda z: math.exp(-r * T) * np.maximum(_paths(S0, r, sigma, T, z) - K, 0.0)
    y = (f(z) + f(-z)) / 2                          # one average per pair
    return float(y.mean()), float(y.std(ddof=1) / math.sqrt(m))
